    key: v.string(),
    createdAt: v.number(),
  })    .index("by_organization_id", ["organizationId"])
    .index("by_organization_id_and_created_at", ["organizationId", "createdAt"]),
  feedback: defineTable({
    organizationId: v.string(),
    conversationId: v.id("conversations"),
    threadId: v.string(),
