    updatedAt: v.number(),
  }).index("by_conversation", ["conversationId"])
    .index("by_organization_id", ["organizationId"])
    .index("by_organization_and_message", ["organizationId", "messageId"])
    .index("by_organization_and_created_at", ["organizationId", "createdAt"]),
  ...financeTables,
});

