const arr = () => Array.from({ length: 4 }, () => 0);
const aBytes = arr();
const bBytes = arr();

/**
 * @param {number} codePoint
 * @param {number[]} bytes
 * @returns {number}
 */
function utf8Bytes(codePoint: number, bytes: number[]) {
  if (codePoint < 0x80) {
    bytes[0] = codePoint;
    return 1;
  }

  let count;
  let offset;

  if (codePoint <= 0x07ff) {
    count = 1;
    offset = 0xc0;
